import {fetchReviewDiscussion,fetchProjectActivity,writeReviewComment} from './cloud.mjs';
import {compareRevisions,diffValue} from './revision-diff.mjs';
import {esc} from './document.mjs';
const sections={project:'Project & issue',organization:'Parties & team',information:'Information & platforms',technical:'Models & standards',coordination:'Coordination & delivery',modules:'BEP content',files:'Files & appendices',appearance:'Branding & print',review:'Review & issues',templates:'Templates & data'};
export function mountReviewWorkspace(root,{project,getProject,notify,navigate}){
 const panel=document.createElement('div');root.replaceChildren(panel);let comments=[],activity=[],busy=false;
 const current=()=>panel.isConnected&&getProject()?.id===project.id;
 const editable=()=>current()&&getProject().accessRole!=='viewer';
 panel.innerHTML=`<section class="form-card"><h2>Compare versions</h2><p>Compare the current draft with a frozen issue, or compare two frozen issues. This does not restore or alter either version. Row numbers are used where no unique row identifier exists.</p><div class="field-grid"><label>Before<select data-version="before"></select></label><label>After<select data-version="after"></select></label></div><button class="button secondary" data-compare>Compare</button><div data-diff></div></section><section class="form-card"><div class="card-heading"><h2>Review discussion</h2><button class="button ghost" data-refresh>Refresh discussion & activity</button></div><p>Private project discussion. Comments are separate from approval evidence and do not block issue automatically. Viewers can read; owners and editors can post, resolve and reopen.</p>${editable()?`<form data-comment-form><label>Related section<select name="section">${Object.entries(sections).map(([k,v])=>`<option value="${k}">${esc(v)}</option>`).join('')}</select></label><label>Comment<textarea name="body" required maxlength="4000" rows="3"></textarea></label><button class="button primary" type="submit">Post comment</button></form>`:''}<label>Show<select data-comment-filter><option value="all">All comments</option><option value="open">Open</option><option value="resolved">Resolved</option></select></label><div data-comments>Loading comments…</div></section><section class="form-card"><h2>Project activity</h2><p>Server-recorded saves and discussion actions from activation onward. Changed paths identify fields and schedules; use version comparison for before/after values. Deleting a project also removes its discussion and activity.</p><div data-activity>Loading activity…</div><button class="button secondary" data-more hidden>Load older activity</button></section>`;
 const options='<option value="draft">Current draft</option>'+project.releases.map(r=>`<option value="${esc(r.id)}">Issue ${r.number} · ${esc(r.revision)} · ${esc(r.issueDate)}</option>`).join('');
 panel.querySelectorAll('[data-version]').forEach(el=>el.innerHTML=options);if(project.releases.length)panel.querySelector('[data-version="before"]').value=project.releases.at(-1).id;
 panel.querySelector('[data-compare]').onclick=()=>{if(!current())return;const p=getProject(),find=id=>id==='draft'?p:p.releases.find(r=>r.id===id)?.snapshot;
 const before=find(panel.querySelector('[data-version="before"]').value),after=find(panel.querySelector('[data-version="after"]').value);if(!before||!after){notify('The selected issue is no longer available. Reopen this view.');return;}
 const diff=compareRevisions(before,after);panel.querySelector('[data-diff]').innerHTML=`<p>${diff.length} differences</p>${diff.map(c=>`<details class="revision-change"><summary>${esc(c.kind)} · ${esc(c.path)}</summary><div class="diff-pair"><div><strong>Before</strong><pre>${esc(diffValue(c.before))}</pre></div><div><strong>After</strong><pre>${esc(diffValue(c.after))}</pre></div></div></details>`).join('')||'<p>No content differences.</p>'}`;};
 function renderComments(){const filter=panel.querySelector('[data-comment-filter]').value;panel.querySelector('[data-comments]').innerHTML=`${comments.length===500?'<p>Latest 500 comments shown.</p>':''}${comments.filter(c=>filter==='all'||(filter==='resolved')===c.resolved).map(c=>`<article class="review-comment"><strong>${c.resolved?'Resolved':'Open'} · ${esc(sections[c.section]||c.section)}</strong><p class="comment-body">${esc(c.body)}</p><small>${esc(c.author_label)} · ${esc(new Date(c.created_at).toLocaleString())}</small>${c.resolved_at?`<p><small>Last status change: ${esc(c.resolved_by)} · ${esc(new Date(c.resolved_at).toLocaleString())}</small></p>`:''}<div class="table-tools"><button class="button ghost" data-comment-go="${esc(c.section)}">Go to section</button>${editable()?`<button class="button secondary" data-resolve="${esc(c.id)}">${c.resolved?'Reopen':'Resolve'}</button>`:''}</div></article>`).join('')||'<p>No matching comments.</p>'}`;
 panel.querySelectorAll('[data-comment-go]').forEach(b=>b.onclick=()=>navigate(b.dataset.commentGo));
 panel.querySelectorAll('[data-resolve]').forEach(b=>b.onclick=async()=>{if(busy||!editable())return;const c=comments.find(c=>c.id===b.dataset.resolve);busy=true;b.disabled=true;try{await writeReviewComment(project.id,c.section,'',c.id,!c.resolved);await refresh();}catch(e){notify(e.message);}finally{busy=false;if(current())b.disabled=false;}});
 }
 function renderActivity(){panel.querySelector('[data-activity]').innerHTML=activity.map(a=>`<article class="review-comment"><strong>${esc(a.action)}${a.version!=null?` · cloud version ${esc(a.version)}`:''}</strong><p>${esc(a.actor_label)} · ${esc(new Date(a.created_at).toLocaleString())}</p><small>${esc((a.changed_paths||[]).join(', '))}</small></article>`).join('')||'<p>No activity recorded since this feature was activated.</p>';}
 async function refresh(){if(!current())return;const result=await Promise.allSettled([fetchReviewDiscussion(project.id),fetchProjectActivity(project.id)]);if(!current())return;
 if(result[0].status==='fulfilled'){comments=result[0].value;renderComments();}else panel.querySelector('[data-comments]').textContent=`Could not load comments: ${result[0].reason.message}`;
 if(result[1].status==='fulfilled'){activity=result[1].value;renderActivity();panel.querySelector('[data-more]').hidden=activity.length<50;}else panel.querySelector('[data-activity]').textContent=`Could not load activity: ${result[1].reason.message}`;
 }
 panel.querySelector('[data-refresh]').onclick=refresh;panel.querySelector('[data-comment-filter]').onchange=renderComments;
 panel.querySelector('[data-more]').onclick=async e=>{const b=e.currentTarget;b.disabled=true;try{const older=await fetchProjectActivity(project.id,activity.at(-1)?.id);if(!current())return;activity=[...activity,...older.filter(a=>!activity.some(old=>old.id===a.id))];renderActivity();b.hidden=older.length<50;}catch(error){notify(error.message);}finally{b.disabled=false;}};
 panel.querySelector('[data-comment-form]')?.addEventListener('submit',async e=>{e.preventDefault();if(busy||!editable())return;const form=e.currentTarget,data=new FormData(form),body=String(data.get('body')).trim();if(!body)return;busy=true;const b=form.querySelector('button');b.disabled=true;try{await writeReviewComment(project.id,String(data.get('section')),body);if(current()){form.elements.body.value='';await refresh();}}catch(error){notify(error.message);}finally{busy=false;b.disabled=false;}});
 refresh();
}
